// Unifica la entrada tolerando payloads de Webhook y extracción directa de CSV con BOM (\ufeff)
const items = $input.all();
const rows = [];

for (const item of items) {
  const j = item.json || {};
  const body = j.body;

  if (body) {
    if (Array.isArray(body)) {
      rows.push(...body);
    } else if (body.leads && Array.isArray(body.leads)) {
      body.origen = 'webhook'
      rows.push(...body.leads);
    } else if (typeof body === 'object' && (body.id !== undefined || body['\ufeffid'] !== undefined)) {
      rows.push(body);
    }
  } else {
    // Proviene del nodo CSV
    if (j.id !== undefined || j['\ufeffid'] !== undefined) {
      j.origen = "csv"
      rows.push(j);
    }
  }
}

// Limpia el carácter BOM (\ufeff) de las llaves de cada fila
return rows.map(r => {
  const cleanRow = {};
  for (const [key, val] of Object.entries(r)) {
    const cleanKey = key.replace(/^\ufeff/, '').trim();
    cleanRow[cleanKey] = val;
  }
  return { json: cleanRow };
});

// Toma el texto del Agente IA o, si falla / no hay API Key, sintetiza un resumen en TEXTO PLANO desde los leads
const agentOut = $input.first()?.json?.output || $input.first()?.json?.text;
const leads = $('4a. Consolidar 13 Leads').first().json.leads_calificados || [];

// Quita cualquier rastro de Markdown que el LLM pudiera colar
const stripMd = s => s
  .replace(/\*\*(.*?)\*\*/g, '$1')
  .replace(/^#{1,6}\s*/gm, '')
  .replace(/`/g, '')
  .replace(/^\s*[*-]\s+/gm, '- ');

let texto = '';

if (agentOut && typeof agentOut === 'string' && agentOut.trim().length > 100) {
  texto = stripMd(agentOut.trim());
} else {
  const catA = leads.filter(l => l.calificacion === 'A');
  const catB = leads.filter(l => l.calificacion === 'B');
  const catC = leads.filter(l => l.calificacion === 'C');
  const desc = leads.filter(l => l.calificacion === 'Descartado');
  const dups = leads.filter(l => l.duplicado_de);
  const rev = leads.filter(l => l.requiere_revision === true);
  const vipB = catB.find(l => Number(l.num_empleados_estimado) >= 200 || /referido/i.test(l.fuente));

  const L = [];
  L.push('ASUNTO: Plan de llamadas y priorización de leads - DARHE');
  L.push('');
  L.push('Hola Christian,');
  L.push('');
  L.push(`Procesamos el lote de prospectos. Quedaron ${leads.length} contactos únicos (se unieron ${dups.length} personas que escribieron por más de un canal): ${catA.length} prioridad A, ${catB.length} B, ${catC.length} C y ${desc.length} descartados.`);
  L.push('');
  L.push('1. A QUIÉN LLAMAR PRIMERO');
  let rank = 1;
  for (const l of [...catA, ...(vipB ? [vipB] : [])]) {
    L.push(`${rank}) ${l.nombre} - ${l.empresa} (${l.ciudad}). Tel: ${l.telefono || 'sin teléfono'}`);
    L.push(`   Por qué: ${l.razon}`);
    L.push(`   Siguiente paso: ${l.siguiente_accion}`);
    rank++;
  }
  L.push('');
  L.push('2. NECESITO TU VISTO BUENO ANTES DE CONTACTAR');
  for (const r of rev) L.push(`- ${r.nombre} (${r.empresa}, ${r.calificacion}): ${r.motivo_revision}`);
  L.push('');
  L.push('3. RESTO DE PROSPECTOS');
  for (const b of catB.filter(x => !vipB || x.id !== vipB.id)) L.push(`- B | ${b.nombre} (${b.empresa}): ${b.razon}`);
  for (const c of catC) L.push(`- C | ${c.nombre} (${c.empresa}): ${c.razon}`);
  for (const d of desc) L.push(`- Descartado | ${d.nombre} (${d.empresa}): ${d.razon}`);
  L.push('');
  L.push('Ningún lead se contacta sin tu validación.');
  texto = L.join('\n');
}

return [{
  json: {
    status: 'success',
    total_leads_unicos: leads.length,
    archivos_generados: [
      '/data/output/leads_calificados.csv',
      '/data/output/leads_calificados.json',
      '/data/output/resumen_christian.txt'
    ],
    resumen_christian_texto: texto,
    leads_calificados: leads
  },
  binary: {
    data: {
      data: Buffer.from(texto, 'utf-8').toString('base64'),
      mimeType: 'text/plain',
      fileName: 'resumen_christian.txt'
    }
  }
}];

