// NODO 2: SOLO LIMPIEZA, NORMALIZACIÓN Y DEDUPLICACIÓN (SURVIVORSHIP)
const items = $input.all().map(i => i.json);

function isNullOrEmpty(val) {
  if (val === null || val === undefined) return true;
  const s = String(val).trim().toLowerCase();
  return s === '' || s === 'nan' || s === 'null' || s === 'none';
}

function cleanBOM(val) {
  return String(val || '').replace(/^\ufeff/, '').trim();
}

function normalizeName(name) {
  if (isNullOrEmpty(name)) return '';
  const str = cleanBOM(name);
  if (str === str.toUpperCase()) {
    return str.toLowerCase().replace(/(?:^|\s|\S)\S/g, a => a.toUpperCase());
  }
  return str;
}

function normalizePhone(val) {
  if (isNullOrEmpty(val)) return null;
  let digits = String(val).replace(/\D/g, '');
  if (!digits || /^0+$/.test(digits) || digits.length < 10) return null;
  if (digits.length === 12 && digits.startsWith('52')) digits = digits.slice(2);
  if (digits.length === 10) return `+52${digits}`;
  return null;
}

function isValidEmail(val) {
  if (isNullOrEmpty(val)) return false;
  const s = String(val).trim().toLowerCase();
  return /^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$/.test(s);
}

function normalizeSegment(val) {
  if (isNullOrEmpty(val)) return 'desconocido';
  const s = String(val).trim().toLowerCase();
  const map = {
    'transportista': 'transportista',
    'transportistas': 'transportista',
    'restaurantero': 'restaurantero',
    'restauranteros': 'restaurantero',
    'restaurant': 'restaurantero',
    'construcción': 'construcción',
    'construccion': 'construcción',
    'empresario': 'empresario',
    'empresarios': 'empresario',
    'hotelería': 'hotelería',
    'hoteleria': 'hotelería'
  };
  return map[s] || s;
}

function hasAccents(str) {
  return /[áéíóúñÁÉÍÓÚÑ]/.test(str || '');
}

// 1. Normalización fila por fila
const normalized = items.map(r => {
  const rawId = r.id !== undefined ? r.id : r['\ufeffid'];
  const rawEmp = r.num_empleados;
  let empNum = null;
  let empDatoOriginal = !isNullOrEmpty(rawEmp) ? cleanBOM(rawEmp) : null;

  if (empDatoOriginal !== null) {
    const parsed = parseInt(empDatoOriginal, 10);
    if (!isNaN(parsed)) empNum = parsed;
  }

  const rawEmail = !isNullOrEmpty(r.email) ? String(r.email).trim().toLowerCase() : null;
  const emailOk = isValidEmail(rawEmail);

  return {
    id: Number(cleanBOM(rawId)),
    fecha: cleanBOM(r.fecha),
    nombre: normalizeName(r.nombre),
    empresa: !isNullOrEmpty(r.empresa) ? cleanBOM(r.empresa) : '',
    email: emailOk ? rawEmail : '',
    email_invalido_detectado: (!emailOk && rawEmail) ? rawEmail : '',
    telefono: normalizePhone(r.telefono) || '',
    segmento: normalizeSegment(r.segmento),
    num_empleados_reportado: empNum,
    num_empleados_raw: empDatoOriginal,
    ciudad: !isNullOrEmpty(r.ciudad) ? cleanBOM(r.ciudad) : '',
    fuente: !isNullOrEmpty(r.fuente) ? cleanBOM(r.fuente) : '',
    mensaje: !isNullOrEmpty(r.mensaje) ? cleanBOM(r.mensaje) : ''
  };
});

// 2. Fusión de duplicados por teléfono (Field-Level Survivorship)
const mergedMap = new Map();

for (const r of normalized) {
  const key = r.telefono !== '' ? r.telefono : `no_phone_${r.id}`;
  const msgEntry = `[${r.fecha} - ${r.fuente}]: ${r.mensaje}`;

  if (!mergedMap.has(key)) {
    mergedMap.set(key, {
      ...r,
      duplicado_de: '',
      emails_alternativos: [],
      mensajes_unidos: [msgEntry],
      mensaje: msgEntry
    });
  } else {
    const master = mergedMap.get(key);
    master.duplicado_de = master.duplicado_de ? `${master.duplicado_de},${r.id}` : String(r.id);

    if (!hasAccents(master.nombre) && hasAccents(r.nombre)) master.nombre = r.nombre;
    if (r.empresa && (!master.empresa || r.empresa.length > master.empresa.length)) master.empresa = r.empresa;
    if (!master.email && r.email) master.email = r.email;
    else if (master.email && r.email && master.email !== r.email) master.emails_alternativos.push(r.email);
    if (master.num_empleados_reportado === null && r.num_empleados_reportado !== null) {
      master.num_empleados_reportado = r.num_empleados_reportado;
    }
    if (r.fuente && !master.fuente.includes(r.fuente)) master.fuente = `${master.fuente}, ${r.fuente}`;

    master.mensajes_unidos.push(msgEntry);
    master.mensaje = master.mensajes_unidos.join(' | ');
  }
}

// Devuelve los 13 leads limpios listos para que el Agente LLM los califique
return Array.from(mergedMap.values()).map(lead => ({
  json: {
    id: lead.id,
    duplicado_de: lead.duplicado_de,
    fecha: lead.fecha,
    nombre: lead.nombre,
    empresa: lead.empresa,
    email: lead.email,
    telefono: lead.telefono,
    segmento: lead.segmento,
    num_empleados_reportado: lead.num_empleados_reportado,
    num_empleados_raw: lead.num_empleados_raw,
    ciudad: lead.ciudad,
    fuente: lead.fuente,
    mensaje: lead.mensaje
  }
}));

// Une los datos normalizados de cada lead con el dictamen estructurado del Agente IA
const leadsLimpios = $('2. Limpieza y Fusión').all();
const respuestasIA = $input.all();

return leadsLimpios.map((item, index) => {
  const lead = item.json;
  const ia = respuestasIA[index]?.json?.output || respuestasIA[index]?.json || {};

  return {
    json: {
      id: lead.id,
      duplicado_de: lead.duplicado_de || '',
      fecha: lead.fecha,
      nombre: lead.nombre,
      empresa: lead.empresa || '',
      email: lead.email || '',
      telefono: lead.telefono || '',
      segmento: lead.segmento,
      num_empleados_reportado: lead.num_empleados_reportado ?? null,
      num_empleados_estimado: ia.num_empleados_estimado ?? lead.num_empleados_reportado ?? null,
      ciudad: lead.ciudad || '',
      fuente: lead.fuente || '',
      mensaje: lead.mensaje,
      calificacion: ia.calificacion || 'B',
      razon: ia.razon || '',
      siguiente_accion: ia.siguiente_accion || '',
      requiere_revision: Boolean(ia.requiere_revision),
      motivo_revision: ia.motivo_revision || ''
    }
  };
});
